	[577] = {
		id = 577,
		key = 'crossSupremacyEliteTip2',
		text = 'In the formation, you may freely choose %d heroes to be elite heroes. Elite heroes can be used one extra time in other formations (maximum 2 uses total). Each team can include a maximum of 2 elite heroes.  ',
		text_vn = 'Trong đội hình, bạn được tự do chọn %d anh hùng làm anh hùng tinh anh. Anh hùng tinh anh được được sử dụng thêm một lần trong các đội hình khác (tối đa sử dụng hai lần). Mỗi đội chỉ được có tối đa 2 anh hùng tinh anh.',
		text_ma = 'Dalam formasi, anda boleh memilih %d wira sebagai wira elit. Wira elit boleh digunakan tambahan sekali dalam formasi lain (maksimum dua kali). Setiap pasukan hanya boleh mempunyai maksimum 2 wira elit.',
		text_en = 'In the formation, you may freely choose %d heroes to be elite heroes. Elite heroes can be used one extra time in other formations (maximum 2 uses total). Each team can include a maximum of 2 elite heroes.  ',
		text_in = 'Dalam formasi, Anda bebas memilih %d pahlawan untuk menjadi pahlawan elit. Pahlawan elit dapat digunakan sekali lagi dalam formasi lain (maksimal dua kali). Setiap tim hanya boleh memiliki maksimal 2 pahlawan elit.',
		text_th = 'ในทีม คุณสามารถเลือกฮีโร่ %d ตัวเป็นฮีโร่ระดับสูงได้ ฮีโร่ระดับสูงสามารถใช้เพิ่มได้อีกหนึ่งครั้งในทีมอื่น (รวมใช้ได้สูงสุดสองครั้ง) แต่ละทีมใช้ได้สูงสุด 2 ฮีโร่ระดับสูง',
		text_ph = 'Sa isang team, maaari kang pumili ng %d bayani bilang elite heroes. Ang elite heroes ay maaaring gamitin nang dagdag na isang beses sa ibang lineup (maximum dalawang beses ang paggamit). Bawat team ay maaaring may hanggang 2 elite heroes.  '
	},
