	[1009] = {
		id = 1009,
		key = 'NewsBreakEgg',
		text = '#C0x5B545B#Congratulations to player #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for winning #C0xE69900#{amount}{gainType} ({rate}x Golden Egg reward) in the Golden Egg Smashing Event!#C0x5B545B#',
		text_vn = '#C0x5B545B#Xin chúc mừng người chơi #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# đã giành được #C0xE69900#{amount}{gainType} ({rate} lần phần thưởng trứng vàng) trong Sự kiện Đập Trứng Vàng!#C0x5B545B#',
		text_ma = '#C0x5B545B#Tahniah kepada pemain #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang memenangi #C0xE69900#{amount}{gainType} (ganjaran telur emas {rate} kali ganda) dalam acara Pecahkan Telur Emas!#C0x5B545B#',
		text_en = '#C0x5B545B#Congratulations to player #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for winning #C0xE69900#{amount}{gainType} ({rate}x Golden Egg reward) in the Golden Egg Smashing Event!#C0x5B545B#',
		text_in = '#C0x5B545B#Selamat kepada pemain #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang telah memenangkan #C0xE69900#{amount}{gainType} ({rate} kali hadiah telur emas) dalam Acara Pukul Telur Emas!',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับผู้เล่น #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# ที่ได้รับ #C0xE69900#{amount}{gainType} (รางวัลทองคำ {rate} เท่า) จากกิจกรรมทุบไข่ทองคำ!#C0x5B545B#',
		text_ph = '#C0x5B545B#Binabati ang manlalaro na si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pagkamit ng #C0xE69900#{amount}{gainType} (x{rate} Golden Egg bonus) sa Golden Egg Event!#C0x5B545B#'
	},
	[1010] = {
		id = 1010,
		key = 'NewsHoldItemInDraw',
		text = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for receiving the rare special gear #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B# through accessory draw. You\'re really lucky!',
		text_vn = '#C0x5B545B#Xin chúc mừng #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#đã nhận được trang bị đặc biệt hiếm có #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B#thông qua chương trình rút thăm phụ kiện. Bạn thật may mắn!',
		text_ma = '#C0x5B545B#Tahniah kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#kerana memperoleh peralatan khas yang sangat jarang #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B#melalui cabutan aksesori. Anda sangat bertuah!',
		text_en = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for receiving the rare special gear #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B# through accessory draw. You\'re really lucky!',
		text_in = '#C0x5B545B#Selamat kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang telah mendapatkan perlengkapan langka #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B# melalui program undian aksesoris. Anda sangat beruntung!',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับ #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#ที่ได้รับอุปกรณ์พิเศษสุดหายาก #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B#จากการสุ่มอุปกรณ์ คุณโชคดีมาก!',
		text_ph = '#C0x5B545B#Binabati si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pagkamit ng bihirang espesyal na kagamitan #C0x8A5C99##LULrole1#{holdItem}#C0x5B545B# mula sa Accessory Draw. Napakaswerte mo!'
	},
