		text_ph = '#C0x5B545B#Binabati ang manlalaro na si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pag-upgrade ng #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# sa Red +1 quality. Malaking pagtaas sa lakas ng team!'
	},
	[1027] = {
		id = 1027,
		key = 'NewsCardStar',
		text = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for upgrading #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# to star level {star}. Your combat power has been greatly enhanced!',
		text_vn = '#C0x5B545B#Chúc mừng #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# đã nâng cấp #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# lên sao {star}. Sức mạnh chiến đấu của bạn đã được tăng cường rất nhiều!',
		text_ma = '#C0x5B545B#Tahniah kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# kerana menaik taraf #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# ke bintang {star}. Kekuatan tempur anda telah meningkat dengan ketara!',
		text_en = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for upgrading #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# to star level {star}. Your combat power has been greatly enhanced!',
		text_in = '#C0x5B545B#Selamat #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# telah meningkatkan #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# ke bintang {star}. Kekuatan tempur Anda telah diperkuat sangat banyak!',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับ#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#ที่อัปเกรด#C0xE77421##L10100##LULcard1#{card}#C0x5B545B#ขึ้นเป็นดาว {star} พลังการต่อสู้ของคุณเพิ่มขึ้นอย่างมาก!',
		text_ph = '#C0x5B545B#Binabati si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pag-upgrade ng #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# sa bituin {star}. Lubos na nadagdagan ang iyong kapangyarihang pandigma!'
	},
	[1028] = {
		id = 1028,
		key = 'NewsPVPTopRank',
		text = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for claiming first place in the arena with overwhelming momentum. Being undefeated is a kind of loneliness...',
		text_vn = '#C0x5B545B#Chúc mừng#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#Giành được vị trí thứ nhất trên đấu trường với khí thế hùng hồn, bất khả chiến bại cũng là một loại cô đơn...',
		text_ma = '#C0x5B545B#Tahniah kepada#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#kerana berjaya meraih tempat pertama di arena dengan semangat yang mengagumkan, tiada siapa dapat mengalahkannya — satu bentuk kesunyian yang hebat...',
		text_en = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for claiming first place in the arena with overwhelming momentum. Being undefeated is a kind of loneliness...',
		text_in = '#C0x5B545B#Selamat #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# Mendapatkan tempat pertama di arena dengan semangat yang membara, tak terkalahkan juga merupakan sebuah kesendirian...',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับ#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#ที่คว้าอันดับหนึ่งในอารีนาด้วยความฮึกเหิมไร้เทียมทาน ความโดดเดี่ยวก็เป็นอีกหนึ่งรสชาติของชัยชนะ...',
		text_ph = '#C0x5B545B#Binabati si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pagkamit ng unang pwesto sa Arena na may di-matitinag na lakas — isang uri ng pag-iisa...'
	},
	[1029] = {
		id = 1029,
		key = 'NewsYZPassFloor40',
		text = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for reaching level 40 in the Pet Challenge after much effort. May they achieve even greater results!',
		text_vn = '#C0x5B545B#Chúc mừng#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# đã đạt đến cấp độ 40 của Thử thách thú cưng sau khi trải qua rất nhiều khó khăn. Chúc anh ấy/cô ấy đạt được kết quả tốt hơn nữa!',
		text_ma = '#C0x5B545B#Tahniah kepada#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# kerana mencapai tahap 40 dalam Cabaran Haiwan Peliharaan selepas pelbagai kesukaran. Semoga berjaya mencapai tahap lebih tinggi!',
		text_en = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for reaching level 40 in the Pet Challenge after much effort. May they achieve even greater results!',
		text_in = '#C0x5B545B#Selamat #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang telah mencapai level 40 dalam Tantangan Pet setelah melewati banyak kesulitan. Semoga dia bisa meraih hasil yang lebih baik lagi!',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับ#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#ที่ผ่านความยากลำบากและถึงเลเวล 40 ในการท้าทายสัตว์เลี้ยง ขอให้เขา/เธอบรรลุผลลัพธ์ที่ดียิ่งขึ้น!',
		text_ph = '#C0x5B545B#Binabati si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pag-abot sa antas 40 ng Pet Challenge matapos lagpasan ang maraming pagsubok. Nawa\'y makamit niya pa ang mas matataas na tagumpay!'
	},
	[1030] = {
		id = 1030,
		key = 'NewsYZPassFloor50',
		text = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for reaching level 50 in the Pet Challenge after much effort. We hope they take it a step further!',
		text_vn = '#C0x5B545B#Chúc mừng#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# đã đạt đến cấp độ 50 của Thử thách thú cưng sau khi trải qua rất nhiều khó khăn. Tôi hy vọng anh ấy/cô ấy có thể tiến thêm một bước nữa!',
		text_ma = '#C0x5B545B#Tahniah kepada#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# kerana mencapai tahap 50 dalam Cabaran Haiwan Peliharaan selepas pelbagai kesukaran. Harap dia boleh melangkah lebih jauh!',
		text_en = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for reaching level 50 in the Pet Challenge after much effort. We hope they take it a step further!',
		text_in = '#C0x5B545B#Selamat #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang telah mencapai level 50 dalam Tantangan Pet setelah melewati banyak kesulitan. Saya berharap dia bisa melangkah lebih jauh lagi!',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับ#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#ที่ผ่านความยากลำบากและถึงเลเวล 50 ในการท้าทายสัตว์เลี้ยง หวังว่าเขา/เธอจะก้าวไปอีกขั้น!',
		text_ph = '#C0x5B545B#Binabati si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pag-abot sa antas 50 ng Pet Challenge. Nawa\'y patuloy siyang umangat pa!'
	},
	[1031] = {
		id = 1031,
		key = 'NewsYZPassFloor60',
		text = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for overcoming all obstacles and reaching the highest level of the Pet Challenge. Now all other mountains feel small!',
		text_vn = '#C0x5B545B#Chúc mừng#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# đã vượt qua mọi khó khăn và đạt đến cấp độ cao nhất của thử thách thú cưng. Điều này thực sự khiến bạn cảm thấy rằng mọi ngọn núi khác đều nhỏ bé!',
		text_ma = '#C0x5B545B#Tahniah kepada#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# kerana berjaya menakluk semua cabaran dan mencapai tahap tertinggi dalam Cabaran Haiwan Peliharaan. Semua gunung lain terasa kecil berbanding ini!',
		text_en = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for overcoming all obstacles and reaching the highest level of the Pet Challenge. Now all other mountains feel small!',
		text_in = '#C0x5B545B#Selamat #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# yang telah melewati semua kesulitan dan mencapai level tertinggi dalam tantangan Pet. Ini benar-benar membuatmu merasa bahwa semua gunung lainnya terasa kecil!',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับ#C0x5C9971##L10100##LULrole1#{name}#C0x5B545B#ที่ฝ่าฟันอุปสรรคและบรรลุระดับสูงสุดของการท้าทายสัตว์เลี้ยง มันทำให้ภูเขาทั้งหลายดูเล็กลงทันที!',
		text_ph = '#C0x5B545B#Binabati si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa matagumpay na pag-abot sa pinakamataas na antas ng Pet Challenge. Tunay na ang ibang bundok ay tila maliit na lang!'
	},
	[1032] = {
