	[1047] = {
		id = 1047,
		key = 'UnionIntro',
		text = 'Welcome to %s, let\'s build a new home together',
		text_vn = 'Chào mừng đến với %s, chúng ta hãy cùng nhau xây dựng một ngôi nhà mới',
		text_ma = 'Selamat datang ke %s, mari kita bina rumah baharu bersama-sama',
		text_en = 'Welcome to %s, let\'s build a new home together',
		text_in = 'Selamat datang di %s, mari kita bangun rumah baru bersama-sama!',
		text_th = 'ยินดีต้อนรับสู่ %s มาร่วมกันสร้างบ้านใหม่ของเราเถอะ',
		text_ph = 'Maligayang pagdating sa %s, magtulungan tayong bumuo ng bagong tahanan'
	},
	[1048] = {
		id = 1048,
		key = 'LuckyCatDesc1',
		text = '#C0x5B545B#Each person has 5 chances.',
		text_vn = '#C0x5B545B#Mỗi người đều có 5 cơ hội.',
		text_ma = '#C0x5B545B#Setiap orang mempunyai 5 peluang.',
		text_en = '#C0x5B545B#Each person has 5 chances.',
		text_in = '#C0x5B545B#Setiap orang memiliki 5 kesempatan.',
		text_th = '#C0x5B545B#แต่ละคนมีโอกาส 5 ครั้ง',
		text_ph = '#C0x5B545B#Bawat tao ay may 5 pagkakataon.'
	},
	[1049] = {
		id = 1049,
		key = 'LuckyCatDesc2',
		text = '#C0x5B545B#There are still more chances',
		text_vn = '#C0x5B545B#Còn nhiều cơ hội hơn nữa',
		text_ma = '#C0x5B545B#Masih banyak peluang lagi',
		text_en = '#C0x5B545B#There are still more chances',
		text_in = '#C0x5B545B#Masih banyak kesempatan lagi',
		text_th = '#C0x5B545B#ยังมีโอกาสอีกมากมาย',
		text_ph = '#C0x5B545B#May mas maraming pagkakataon pa'
	},
	[1050] = {
		id = 1050,
		key = 'pass_battle',
		text = '#C0x5B545B#Thanks to your heroic performance in yesterday\'s challenge, you can directly skip this battle stage and receive all stars and the highest score. Do you want to continue? (You can skip up to %s stages today)',
		text_vn = '#C0x5B545B#Nhờ màn thể hiện anh hùng của bạn trong thử thách ngày hôm qua, bạn có thể bỏ qua trực tiếp cấp độ chiến đấu này và giành được toàn bộ sao cùng điểm cao nhất. Bạn có muốn tiếp tục không? (Bạn có thể bỏ qua tối đa %s cấp độ hôm nay)',
		text_ma = '#C0x5B545B#Kerana aksi kepahlawanan anda dalam cabaran semalam, anda boleh melangkau tahap pertempuran ini dan menerima semua bintang dan mata tertinggi. Adakah anda ingin teruskan? (Anda boleh langkau sehingga %s tahap hari ini)',
		text_en = '#C0x5B545B#Thanks to your heroic performance in yesterday\'s challenge, you can directly skip this battle stage and receive all stars and the highest score. Do you want to continue? (You can skip up to %s stages today)',
		text_in = '#C0x5B545B#Berkat aksi heroik Anda dalam tantangan kemarin, Anda bisa langsung melewati level pertempuran ini dan mendapatkan seluruh bintang dengan poin tertinggi. Apakah Anda ingin melanjutkan? (Anda dapat melewati hingga %s level hari ini)',
		text_th = '#C0x5B545B#จากการแสดงความกล้าหาญของคุณในความท้าทายเมื่อวาน คุณสามารถข้ามด่านนี้ได้ทันทีและรับดาวเต็มพร้อมคะแนนสูงสุด คุณต้องการดำเนินการต่อหรือไม่ (คุณสามารถข้ามได้สูงสุด %s ด่านในวันนี้)',
		text_ph = '#C0x5B545B#Dahil sa iyong kabayanihang ipinakita sa kahapon na hamon, maaari mong laktawan ang antas ng labang ito at makuha ang lahat ng bituin at pinakamataas na puntos. Nais mo bang magpatuloy? (Maaari kang laktawan ng hanggang %s na antas ngayong araw)'
	},
