	[1068] = {
		id = 1068,
		key = 'FriendCloneInvite',
		text = '#C0x5C9971#%s#C0x5B545B# is under siege by #C0xE77421#%s#C0x5B545B# in the illusion chamber of %s. Come and help! #LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#',
		text_vn = '#C0x5C9971#%s#C0x5B545B# đang bị bao vây bởi #C0xE77421#%s#C0x5B545B# trong phòng ảo ảnh của %s, hãy đến giúp đỡ #LULnature_room_id##Icity/adventure/clone_battle/imag_ljjr.png-182-54#',
