		key = 'NewsCardInGroupDrawUp',
		text = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for obtaining #C0xE69900#{star}#C0x5B545B# star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# through the Optional Draw. Your power has greatly increased!',
		text_vn = '#C0x5B545B#Chúc mừng #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# đã nhận được #C0xE69900#{star}#C0x5B545B#star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# thông qua việc rút bài tự chọn. Sức mạnh của bạn đã được tăng cường rất nhiều!',
		text_ma = '#C0x5B545B#Tahniah kepada #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# kerana memperoleh #C0xE69900#{star}#C0x5B545B#bintang #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# melalui cabutan pilihan. Kekuatan anda telah meningkat dengan ketara!',
		text_en = '#C0x5B545B#Congratulations to #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# for obtaining #C0xE69900#{star}#C0x5B545B# star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# through the Optional Draw. Your power has greatly increased!',
		text_in = '#C0x5B545B#Selamat #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# telah menerima #C0xE69900#{star}#C0x5B545B#bintang #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# melalui pemilihan kartu. Kekuatanmu telah meningkat sangat banyak!',
		text_th = '#C0x5B545B#ขอแสดงความยินดีกับ #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# ที่ได้รับ #C0xE69900#{star}#C0x5B545B# ดาว #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# จากการสุ่มการ์ดเลือกเอง พลังของคุณเพิ่มขึ้นอย่างมาก!',
		text_ph = '#C0x5B545B#Binabati si #C0x5C9971##L10100##LULrole1#{name}#C0x5B545B# sa pagkamit ng #C0xE69900#{star}#C0x5B545B#star #C0xE77421##L10100##LULcard1#{card}#C0x5B545B# sa pamamagitan ng piniling draw. Lubhang lumakas ang iyong kapangyarihan!'
	},
	[1106] = {
		id = 1106,
		key = 'MarqueeCardInGroupDrawUp',
		text = '#C0x5B545B#Commander #C0x5C9971#{name}#C0x5B545B# received #C0xE69900#{star}#C0x5B545B# star #C0xE77421#{card}#C0x5B545B# in [Optional Draw>!',
		text_vn = '#C0x5B545B#Chỉ huy #C0x5C9971#{name}#C0x5B545B# đã nhận được #C0xE69900#{star}#C0x5B545B#star#C0xE77421#{card}#C0x5B545B# trong [Chọn bài rút>!',
		text_ma = '#C0x5B545B#Komander #C0x5C9971#{name}#C0x5B545B# telah memperoleh #C0xE69900#{star}#C0x5B545B#bintang#C0xE77421#{card}#C0x5B545B# dalam [Cabutan Pilihan>!',
		text_en = '#C0x5B545B#Commander #C0x5C9971#{name}#C0x5B545B# received #C0xE69900#{star}#C0x5B545B# star #C0xE77421#{card}#C0x5B545B# in [Optional Draw>!',
		text_in = '#C0x5B545B#Komandan #C0x5C9971#{name}#C0x5B545B# telah menerima #C0xE69900#{star}#C0x5B545B#bintang #C0xE77421#{card}#C0x5B545B# dalam [Pemilihan Tarik Kartu>!',
		text_th = '#C0x5B545B#ผู้บัญชาการ #C0x5C9971#{name}#C0x5B545B# ได้รับ #C0xE69900#{star}#C0x5B545B# ดาว#C0xE77421#{card}#C0x5B545B# ใน [สุ่มเลือกการ์ด>!',
		text_ph = '#C0x5B545B#Tagapamuno #C0x5C9971#{name}#C0x5B545B# ay nakakuha ng #C0xE69900#{star}#C0x5B545B#star#C0xE77421#{card}#C0x5B545B# mula sa [Piniling Draw>!'
	},
