	[1109] = {
		id = 1109,
		key = 'MarqueeCrossSupremacyTopRank',
		text = '#Icity/marquee/logo_qf_txt.png-90-50##C0x5B545B#Congratulations #C0x5C9971#{roleName1}#C0x5B545B#, [{channel2}> from [{channel1}>#{roleName2}#C0x5B545B# and #C0x5C9971#{roleName3}#C0x5B545B# from [{channel3}> ranked in the top three of the world\'s best Budokai gameplay. Truly enviable!',
		text_vn = '#Icity/marquee/logo_qf_txt.png-90-50##C0x5B545B#Xin chúc mừng #C0x5C9971#{roleName1}#C0x5B545B#, [{channel2 }> của [{channel1}>#{roleName2}#C0x5B545B# và #C0x5C9971#{roleName3}#C0x5B545B# của [{channel3}> được xếp hạng trong top ba lối chơi Budokai hay nhất thế giới, điều này thực sự đáng ghen tị với những người khác ',
		text_ma = '#Icity/marquee/logo_qf_txt.png-90-50##C0x5B545B#Tahniah kepada #C0x5C9971#{roleName1}#C0x5B545B#, [{channel2 }> dari [{channel1}>#{roleName2}#C0x5B545B# dan #C0x5C9971#{roleName3}#C0x5B545B# dari [{channel3}> telah disenaraikan dalam tiga teratas mod permainan Budokai terbaik dunia, sesuatu yang benar-benar dicemburui orang lain',
		text_en = '#Icity/marquee/logo_qf_txt.png-90-50##C0x5B545B#Congratulations #C0x5C9971#{roleName1}#C0x5B545B#, [{channel2}> from [{channel1}>#{roleName2}#C0x5B545B# and #C0x5C9971#{roleName3}#C0x5B545B# from [{channel3}> ranked in the top three of the world\'s best Budokai gameplay. Truly enviable!',
		text_in = '#Icity/marquee/logo_qf_txt.png-90-50##C0x5B545B#Selamat kepada #C0x5C9971#{roleName1}#C0x5B545B#, [{channel2 }> dari [{channel1}>#{roleName2}#C0x5B545B# dan #C0x5C9971#{roleName3}#C0x5B545B# dari [{channel3}> yang telah berhasil menduduki peringkat tiga besar dalam permainan Budokai terbaik di dunia, ini benar-benar membuat orang lain iri!',
		text_th = '#Icity/marquee/logo_qf_txt.png-90-50##C0x5B545B#ขอแสดงความยินดีกับ #C0x5C9971#{roleName1}#C0x5B545B#, [{channel2 }> ของ [{channel1}>#{roleName2}#C0x5B545B# และ #C0x5C9971#{roleName3}#C0x5B545B# จาก [{channel3}> ติดอันดับสามอันดับแรกของโหมด Budokai ที่ดีที่สุดในโลก ซึ่งทำให้ผู้เล่นอื่นต้องอิจฉา',
		text_ph = '#Icity/marquee/logo_qf_txt.png-90-50##C0x5B545B#Binabati si #C0x5C9971#{roleName1}#C0x5B545B#, [{channel2 }> mula sa [{channel1}>#{roleName2}#C0x5B545B# at si #C0x5C9971#{roleName3}#C0x5B545B# mula sa [{channel3}> na napabilang sa nangungunang tatlong pinakamahusay na manlalaro ng Budokai sa mundo, tunay na kahanga-hanga at kinaiinggitan!'
	},
	[1110] = {
		id = 1110,
		key = 'MarqueeCrossSupremacyTopHistoryRefresh',
		text = '#C0x5B545B#The exciting No.1 World Budokai showdown has been refreshed, come and worship.',
		text_vn = '#C0x5B545B#Cuộc đọ sức hấp dẫn tại Budokai số 1 Thế giới đã được làm mới, hãy đến chiêm bái',
		text_ma = '#C0x5B545B#Pertarungan menarik dalam Budokai No.1 Dunia telah diperbaharui, mari datang menyaksikan',
		text_en = '#C0x5B545B#The exciting No.1 World Budokai showdown has been refreshed, come and worship.',
		text_in = '#C0x5B545B#Pertarungan menarik di Budokai nomor 1 Dunia telah diperbarui, ayo datang dan lihat.',
		text_th = '#C0x5B545B#การแข่งขันอันดุเดือดของ Budokai อันดับ 1 ของโลกถูกรีเฟรชแล้ว รีบไปชมกัน!',
		text_ph = '#C0x5B545B#Ang kapana-panabik na laban sa World No.1 Budokai ay na-refresh, halina’t saksihan ito'
	},
