	[6170] = {
		id = 6170,
		key = 'perfectNvalueTips',
		text = '#C0x5B545B#You currently have #C0xF76B45#perfect unlocked attributes #C0x5B545B#. Refining may overwrite them. \n Do you want to continue refining?',
		text_vn = '#C0x5B545B#Hiện tại có #C0xF76B45#vật phẩm thuộc tính hoàn hảo đã mở khóa #C0x5B545B#. Nếu bạn tiếp tục tinh chỉnh chúng, chúng có thể bị mất. \nBạn có muốn tiếp tục quá trình thanh lọc này không?',
		text_ma = '#C0x5B545B#Kini terdapat #C0xF76B45#barang sifat sempurna telah dibuka kunci #C0x5B545B#. Jika anda teruskan penapisan, ia mungkin hilang. \nAdakah anda mahu teruskan proses ini?  ',
		text_en = '#C0x5B545B#You currently have #C0xF76B45#perfect unlocked attributes #C0x5B545B#. Refining may overwrite them. \n Do you want to continue refining?',
		text_in = '#C0x5B545B#Saat ini ada #C0xF76B45#item atribut sempurna yang telah dibuka #C0x5B545B#. Jika Anda terus menyempurnakannya, bisa hilang. \nApakah Anda ingin melanjutkan proses penyempurnaan ini?',
		text_th = '#C0x5B545B#ขณะนี้มี #C0xF76B45#ไอเทมคุณสมบัติที่สมบูรณ์แบบถูกปลดล็อกแล้ว #C0x5B545B#. หากคุณทำการปรับแต่งต่อ อาจสูญเสียคุณสมบัตินั้นได้ \nคุณต้องการดำเนินการล้างค่านี้ต่อหรือไม่?',
		text_ph = '#C0x5B545B#Mayroong kasalukuyang #C0xF76B45#perfect attribute item na na-unlock na #C0x5B545B#. Kung ipagpapatuloy mo ang pag-fine tune, maaari itong mawala. \nNais mo bang ipagpatuloy ang prosesong ito ng refinement?  '
	},
