	[6804] = {
		id = 6804,
		key = 'rebirthTip',
		text = 'There is only one copy of this hero in your bag. After disassembly, the active bond effect will be lost. Do you still want to continue?  ',
		text_vn = 'Anh hùng này trong túi chỉ có một, sau khi phân giải, hiệu ứng kết nối đã kích hoạt sẽ mất, bạn có muốn tiếp tục không?',
		text_ma = 'Wira ini hanya satu dalam beg, selepas hancur, kesan sambungan yang aktif akan hilang, mahu teruskan?',
		text_en = 'There is only one copy of this hero in your bag. After disassembly, the active bond effect will be lost. Do you still want to continue?  ',
		text_in = 'Pahlawan ini hanya ada satu di tas Anda, setelah dibongkar, efek koneksi yang telah diaktifkan akan hilang, apakah Anda ingin melanjutkan?',
		text_th = 'ฮีโร่นี้มีแค่ตัวเดียวในกระเป๋า หลังจากแยก เอฟเฟกต์เชื่อมต่อที่ถูกเปิดจะหายไป คุณต้องการดำเนินการต่อหรือไม่?',
		text_ph = 'Isa lang ang bayani na ito sa bag, kapag na-disassemble mawawala ang na-activate na link effect, gusto mo bang ipagpatuloy?'
	},
	[6805] = {
		id = 6805,
		key = 'rebirthTipDouble',
		text = 'There is only one copy of this hero in your bag. After disassembly, the bond effect will be lost, and it is of high rarity. Do you still want to disassemble?  ',
		text_vn = 'Anh hùng này trong túi chỉ có một, sau khi phân giải, hiệu ứng kết nối đã kích hoạt sẽ mất; và độ hiếm cao, bạn có muốn tiếp tục phân giải không?',
		text_ma = 'Wira ini hanya satu dalam beg, selepas hancur, kesan sambungan aktif akan hilang; dan jarang tinggi, mahu teruskan hancur?',
		text_en = 'There is only one copy of this hero in your bag. After disassembly, the bond effect will be lost, and it is of high rarity. Do you still want to disassemble?  ',
		text_in = 'Pahlawan ini hanya ada satu di tas Anda, setelah dibongkar, efek koneksi yang telah diaktifkan akan hilang; dan kelangkaannya tinggi, apakah Anda ingin melanjutkan untuk membongkar?',
		text_th = 'ฮีโร่นี้มีแค่ตัวเดียวในกระเป๋า หลังจากแยก เอฟเฟกต์เชื่อมต่อที่ถูกเปิดจะหายไป และมีความหายากสูง คุณต้องการแยกต่อหรือไม่?',
		text_ph = 'Isa lang ang bayani na ito sa bag, kapag na-disassemble mawawala ang na-activate na link effect; at mataas ang rarity, gusto mo bang ipagpatuloy ang pag-disassemble?'
	},
