	[7498] = {
		id = 7498,
		key = 'selectCardMaterialsMega',
		text = '#C0x5B545B#This hero has invested development materials, #C0xF76B45#consuming will not refund any materials,#C0x5B545B# proceed with selection?#C0x60C456# (materials can be refunded via rebirth)  ',
		text_vn = '#C0x5B545B#Anh hùng này đã được đầu tư nguyên liệu phát triển, #C0xF76B45#sau khi tiêu hao sẽ không được hoàn lại bất kỳ thứ gì,#C0x5B545B# có tiếp tục chọn không? #C0x60C456# (được hoàn trả nguyên liệu phát triển thông qua tái sinh)',
		text_ma = '#C0x5B545B#Wira ini telah dilaburkan bahan pembangunan, #C0xF76B45#selepas penggunaan, tiada apa yang akan dipulangkan,#C0x5B545B# adakah anda ingin terus memilih? #C0x60C456# (bahan pembangunan boleh dipulangkan melalui penukaran semula)',
		text_en = '#C0x5B545B#This hero has invested development materials, #C0xF76B45#consuming will not refund any materials,#C0x5B545B# proceed with selection?#C0x60C456# (materials can be refunded via rebirth)  ',
		text_in = '#C0x5B545B#Pahlawan ini telah diinvestasikan bahan pengembangan, #C0xF76B45#setelah digunakan, tidak ada bahan yang akan dikembalikan,#C0x5B545B# apakah Anda ingin melanjutkan memilih? #C0x60C456# (bahan pengembangan dapat dikembalikan melalui kelahiran kembali)',
		text_th = '#C0x5B545B#ฮีโร่นี้ได้ลงทุนวัตถุดิบพัฒนาแล้ว #C0xF76B45#หากใช้ไปจะไม่สามารถคืนวัตถุดิบใดๆ ได้#C0x5B545B# คุณต้องการเลือกต่อหรือไม่? #C0x60C456# (สามารถคืนวัตถุดิบพัฒนาได้ผ่านการคืนชีพ)',
		text_ph = '#C0x5B545B#Ang bayani na ito ay na-invest na sa mga materyales sa pag-unlad, #C0xF76B45#matapos magamit, hindi na maibabalik ang mga materyales,#C0x5B545B# nais mo bang ipagpatuloy ang pagpili? #C0x60C456# (ang mga materyales sa pag-unlad ay ibabalik sa pamamagitan ng muling pagsilang)'
	},
