	[7696] = {
		id = 7696,
		key = 'gymGateDesc',
		text = '#LOC0x5A545B##F38##C0xFEFDEC#Challenge #C0xAEE97E#Any #C0xFEFDEC#overcome obstacles and receive enhancement materials for Yuhun\nAfter overcoming all difficulties successfully, you can challenge to become the honorable king of #C0xECB72A# this server',
		text_vn = '#LOC0x5A545B##F38##C0xFEFDEC#Thử thách #C0xAEE97E#Bất kỳ #C0xFEFDEC# vượt khó và nhận nguyên liệu cường hóa cho Yuhun\nSau khi vượt qua mọi khó khăn thành công, bạn có thể thách đấu trở thành vị vua danh dự của #C0xECB72A# máy chủ này',
		text_ma = '#LOC0x5A545B##F38##C0xFEFDEC#Cabaran #C0xAEE97E#Apa sahaja #C0xFEFDEC# mengatasi kesulitan dan menerima bahan peningkatan untuk Yuhun\nSelepas mengatasi semua kesukaran dengan jayanya, anda boleh mencabar untuk menjadi raja kehormatan bagi #C0xECB72A# pelayan ini',
		text_en = '#LOC0x5A545B##F38##C0xFEFDEC#Challenge #C0xAEE97E#Any #C0xFEFDEC#overcome obstacles and receive enhancement materials for Yuhun\nAfter overcoming all difficulties successfully, you can challenge to become the honorable king of #C0xECB72A# this server',
		text_in = '#LOC0x5A545B##F38##C0xFEFDEC#Tantangan #C0xAEE97E#Apapun #C0xFEFDEC# atasi kesulitan dan dapatkan bahan peningkatan untuk Yuhun\nSetelah berhasil melewati semua kesulitan, Anda dapat tantang untuk menjadi Raja Kehormatan dari #C0xECB72A# server ini',
		text_th = '#LOC0x5A545B##F38##C0xFEFDEC#ท้าทาย #C0xAEE97E#แบบใดก็ได้ #C0xFEFDEC#ฝ่าฟันความยากลำบากและรับวัสดุเสริมพลังให้กับ Yuhun\nเมื่อผ่านด่านความยากทั้งหมด คุณสามารถท้าชิงเป็นราชาแห่งเกียรติยศของ #C0xECB72A# เซิร์ฟเวอร์นี้ได้',
		text_ph = '#LOC0x5A545B##F38##C0xFEFDEC#Pagsubok #C0xAEE97E#Anumang #C0xFEFDEC# magtagumpay sa hirap at makakuha ng materyal na pagpapalakas para sa Yuhun\nPagkatapos magtagumpay sa lahat ng hirap, maaari kang maglaban upang maging hari ng karangalan ng #C0xECB72A# server na ito'
	},
