	[7755] = {
		id = 7755,
		key = 'reunionGiftText',
		text = '#C0x5B545B#Hello! Long time no see ~ I counted on my fingers and realized that you have been away from this world for %s days. Your hero team has been stuck in %s. Without your brilliant leadership, the heroes are a bit discouraged... But fortunately, you are back. The heroes will be very happy to reunite with you and fight alongside you! \n During your absence, our world has also changed rapidly. We have added some exciting new systems, optimized many issues affecting the experience, and found more and more powerful heroes... This time, I hope this world can bring more happiness to your free time. Now that you’re back, stay with us! \n This is the customized reward content for you. With it, you will surely feel more comfortable, so please accept it quickly!',
		text_vn = '#C0x5B545B#Xin chào! Đã lâu không gặp ~ Tôi đếm trên đầu ngón tay và phát hiện ra rằng bạn đã không còn ở thế giới này được %s ngày. Đội anh hùng của bạn đã bị mắc kẹt trong %s. Nếu không có sự lãnh đạo tháo vát của bạn, các anh hùng sẽ có chút chán nản... Nhưng may mắn thay, bạn đã trở lại. Các anh hùng sẽ rất vui khi được đoàn tụ với bạn và sát cánh chiến đấu! \n Trong thời gian bạn rời đi, thế giới của chúng ta cũng đã thay đổi nhanh chóng. Chúng tôi đã thêm một số hệ thống thú vị mới, tối ưu hóa nhiều vấn đề ảnh hưởng đến trải nghiệm và tìm thấy ngày càng nhiều anh hùng mạnh mẽ... Lần này, tôi hy vọng thế giới này có thể mang lại nhiều hạnh phúc hơn cho thời gian rảnh rỗi của bạn. Bây giờ bạn đã trở lại, hãy ở lại! \n Đây là nội dung phần thưởng được tùy chỉnh dành cho bạn. Có nó chắc chắn bạn sẽ thấy thoải mái hơn nên hãy nhanh chóng chấp nhận nhé!',
		text_ma = '#C0x5B545B#Hai! Sudah lama tidak berjumpa ~ Saya mengira dengan jari dan mendapati anda sudah tidak berada dalam dunia ini selama %s hari. Pasukan wira anda terperangkap di dalam %s. Tanpa kepimpinan bijaksana anda, wira-wira agak kecewa... Tetapi nasib baik, anda kembali. Wira-wira akan sangat gembira kerana bertemu semula dengan anda dan berjuang bersama! \n Semasa anda pergi, dunia kita telah berubah dengan cepat. Kami telah menambah beberapa sistem baru yang menarik, mengoptimumkan pelbagai masalah yang mempengaruhi pengalaman dan menemui lebih ramai wira yang kuat... Kali ini, saya berharap dunia ini dapat membawa lebih banyak kebahagiaan untuk masa lapang anda. Sekarang anda sudah kembali, tinggal lah! \n Ini adalah kandungan hadiah yang disesuaikan khas untuk anda. Dengan hadiah ini, sudah pasti anda akan merasa lebih selesa, jadi terima dengan segera ya!',
		text_en = '#C0x5B545B#Hello! Long time no see ~ I counted on my fingers and realized that you have been away from this world for %s days. Your hero team has been stuck in %s. Without your brilliant leadership, the heroes are a bit discouraged... But fortunately, you are back. The heroes will be very happy to reunite with you and fight alongside you! \n During your absence, our world has also changed rapidly. We have added some exciting new systems, optimized many issues affecting the experience, and found more and more powerful heroes... This time, I hope this world can bring more happiness to your free time. Now that you’re back, stay with us! \n This is the customized reward content for you. With it, you will surely feel more comfortable, so please accept it quickly!',
		text_in = '#C0x5B545B#Halo! Sudah lama tidak bertemu ~ Saya menghitung dengan jari dan menyadari bahwa Anda sudah tidak ada di dunia ini selama %s hari. Tim pahlawan Anda terjebak di %s. Tanpa kepemimpinan Anda yang terampil, para pahlawan sedikit kehilangan semangat... Tapi untungnya, Anda sudah kembali. Para pahlawan akan sangat senang bertemu kembali dengan Anda dan berjuang bersama! \n Selama Anda pergi, dunia kami juga berkembang pesat. Kami telah menambahkan beberapa sistem baru yang menarik, mengoptimalkan banyak masalah yang memengaruhi pengalaman, dan menemukan semakin banyak pahlawan kuat... Kali ini, saya berharap dunia ini dapat memberikan lebih banyak kebahagiaan untuk waktu luang Anda. Sekarang Anda sudah kembali, tetaplah tinggal! \n Ini adalah konten hadiah khusus untuk Anda. Dengan hadiah ini, Anda pasti akan merasa lebih nyaman, jadi segera terima ya!',
		text_th = '#C0x5B545B#สวัสดี! ไม่ได้เจอกันนานเลย~ ฉันนับนิ้วดูแล้วพบว่าคุณหายไปจากโลกนี้มาแล้ว %s วัน ทีมฮีโร่ของคุณติดอยู่ใน %s หากไม่มีการนำอันชาญฉลาดของคุณ เหล่าฮีโร่อาจรู้สึกหดหู่... แต่โชคดีที่คุณกลับมาแล้ว เหล่าฮีโร่จะดีใจมากที่ได้กลับมาร่วมรบเคียงข้างคุณอีกครั้ง! \n ในช่วงเวลาที่คุณไม่อยู่ โลกของเราก็เปลี่ยนแปลงอย่างรวดเร็ว เราได้เพิ่มระบบใหม่ ๆ ที่น่าสนใจ ปรับปรุงปัญหาที่รบกวนประสบการณ์ และค้นพบฮีโร่ที่แข็งแกร่งมากขึ้นเรื่อย ๆ... คราวนี้ หวังว่าโลกนี้จะมอบความสุขยิ่งขึ้นในเวลาว่างของคุณ ตอนนี้คุณกลับมาแล้ว ขอให้อยู่ต่อไปนะ! \n ต่อไปนี้คือของรางวัลที่ปรับมาเพื่อคุณ หวังว่าจะช่วยให้คุณรู้สึกสบายใจขึ้น รีบรับเลยนะ!',
		text_ph = '#C0x5B545B#Kamusta! Matagal na tayong hindi nagkita ~ Binilang ko sa mga daliri ko at napansin ko na hindi ka na nagbabalik sa mundong ito sa loob ng %s na araw. Ang iyong mga bayani ay na-stranded sa %s. Kung wala ang iyong mahusay na pamumuno, medyo mawawala ang gana ng iyong mga bayani... Pero mabuti na lang at bumalik ka. Masaya ang mga bayani na muling makasama ka at lumaban nang magkasama! \n Habang ikaw ay wala, mabilis na nagbago ang aming mundo. Nagdagdag kami ng ilang bagong sistema, pinahusay ang maraming isyu na nakakaapekto sa karanasan, at nakahanap ng mas malalakas na bayani... Sa pagkakataong ito, umaasa kami na ang mundong ito ay magbibigay ng higit pang kasiyahan sa iyong libreng oras. Ngayon na ikaw ay bumalik, manatili ka na! \n Narito ang iyong pasadyang gantimpala. Siguradong magugustuhan mo ito, kaya huwag mag-atubiling kunin ito!'
	},
	[7756] = {
		id = 7756,
		key = 'reunionSignText',
		text = '#C0xFFFFFF##Pfont/youmi.ttf# Currently offline #C0x99FF99##Pfont/youmi.ttf#%d days #C0xFFFFFF##Pfont/youmi.ttf#, receive daily rewards every day!',
		text_vn = '#C0xFFFFFF##Pfont/youmi.ttf# Trước mắt offline #C0x99FF99##Pfont/youmi.ttf#%d ngày #C0xFFFFFF##Pfont/youmi.ttf#, mỗi ngày đánh dấu nhưng nhận lấy trở xuống ban thưởng nội dung!',
		text_ma = '#C0xFFFFFF##Pfont/youmi.ttf# Anda telah offline selama #C0x99FF99##Pfont/youmi.ttf#%d hari #C0xFFFFFF##Pfont/youmi.ttf#, setiap hari tanda tetapi menerima hadiah daripada kandungan!',
		text_en = '#C0xFFFFFF##Pfont/youmi.ttf# Currently offline #C0x99FF99##Pfont/youmi.ttf#%d days #C0xFFFFFF##Pfont/youmi.ttf#, receive daily rewards every day!',
		text_in = '#C0xFFFFFF##Pfont/youmi.ttf# Saat ini offline #C0x99FF99##Pfont/youmi.ttf#%d hari #C0xFFFFFF##Pfont/youmi.ttf#, setiap hari mencatat dan menerima hadiah!',
		text_th = '#C0xFFFFFF##Pfont/youmi.ttf# ออฟไลน์ก่อนหน้านี้ #C0x99FF99##Pfont/youmi.ttf#%d วัน #C0xFFFFFF##Pfont/youmi.ttf#, เช็คอินทุกวันเพื่อรับรางวัล!',
		text_ph = '#C0xFFFFFF##Pfont/youmi.ttf# Sa ngayon ikaw ay offline ng #C0x99FF99##Pfont/youmi.ttf# %d na araw #C0xFFFFFF##Pfont/youmi.ttf#, bawat araw ay may espesyal na gantimpala para sa iyo!'
	},
