	[7763] = {
		id = 7763,
		key = 'reunionTaskOldText',
		text = '#L00000010##C0x5B545B#Congratulations, you have successfully linked with #L00000010##C0xF13B54# [ %s > #L00000010##C0x5B545B#]!',
		text_vn = '#L00000010##C0x5B545B#Chúc mừng bạn đã liên kết thành công với #L00000010##C0xF13B54# [ %s > #L00000010##C0x5B545B#!',
		text_ma = '#L00000010##C0x5B545B#Tahniah, anda telah berjaya berhubung dengan #L00000010##C0xF13B54# [ %s > #L00000010##C0x5B545B#!  ',
		text_en = '#L00000010##C0x5B545B#Congratulations, you have successfully linked with #L00000010##C0xF13B54# [ %s > #L00000010##C0x5B545B#]!',
		text_in = '#L00000010##C0x5B545B#Selamat Anda telah berhasil terhubung dengan #L00000010##C0xF13B54# [ %s > #L00000010##C0x5B545B#!',
		text_th = '#L00000010##C0x5B545B#ขอแสดงความยินดีที่คุณเชื่อมโยงสำเร็จกับ #L00000010##C0xF13B54# [ %s > #L00000010##C0x5B545B#!',
		text_ph = '#L00000010##C0x5B545B#Binabati kita, matagumpay mong nakakonekta ang #L00000010##C0xF13B54# [ %s > #L00000010##C0x5B545B#!]'
	},
	[7764] = {
		id = 7764,
		key = 'reunionTaskBindToText',
		text = '#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#* Only shows missions you have cooperated in, please remind your friends to complete their daily personal missions to receive more rewards from the chest!',
		text_vn = '#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#* Chỉ hiển thị các nhiệm vụ bạn hợp tác tham gia, cần nhắc nhở bạn bè của bạn hoàn thành nhiệm vụ cá nhân mỗi ngày để nhận thêm quà từ rương!',
		text_ma = '#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#* Hanya memaparkan misi yang anda sertai bersama. Ingatkan rakan-rakan anda untuk menyelesaikan misi peribadi mereka setiap hari bagi menerima hadiah tambahan dari peti hadiah!',
		text_en = '#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#* Only shows missions you have cooperated in, please remind your friends to complete their daily personal missions to receive more rewards from the chest!',
		text_in = '#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#* Hanya menampilkan misi yang Anda kerjakan bersama, ingatkan teman Anda untuk menyelesaikan misi pribadi mereka setiap hari untuk menerima lebih banyak hadiah dari peti!',
		text_th = '#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#* จะแสดงเฉพาะภารกิจที่คุณร่วมมือกันเท่านั้น โปรดเตือนเพื่อนของคุณให้ทำภารกิจรายวันเพื่อรับของขว้าเพิ่มเติมจากหีบสมบัติ!',
		text_ph = '#L00100010##LOC0xFFFFFF##LOS3##C0xF13B54#* Tanging mga gawain ng kooperasyon ang ipinapakita, siguraduhing ipaalala sa iyong mga kaibigan na tapusin ang kanilang mga personal na gawain araw-araw upang makakuha pa ng mga gantimpala mula sa chest!'
	},
	[7765] = {
		id = 7765,
		key = 'reunionBindTextByReunion',
		text = '#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#* Bind a senior commander to start the reunion mission. Complete the mission to receive mission rewards. You can also receive point rewards with the bound senior commander.',
		text_vn = '#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#*Ràng buộc một chỉ huy cấp cao để bắt đầu nhiệm vụ đoàn tụ. Hoàn thành nhiệm vụ để nhận phần thưởng nhiệm vụ. Ngoài ra, bạn cũng có thể nhận được phần thưởng điểm với chỉ huy cấp cao bị ràng buộc.',
		text_ma = '#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#* Ikat komander peringkat tinggi untuk memulakan misi pertemuan semula. Selesaikan misi untuk menerima ganjaran misi. Selain itu, anda juga boleh menerima ganjaran mata dengan komander peringkat tinggi yang telah diikat.',
		text_en = '#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#* Bind a senior commander to start the reunion mission. Complete the mission to receive mission rewards. You can also receive point rewards with the bound senior commander.',
		text_in = '#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#* Ikat seorang pemimpin senior untuk memulai misi reuni. Selesaikan misi untuk menerima hadiah misi. Selain itu, Anda juga dapat menerima hadiah poin dengan pemimpin senior yang terhubung.',
		text_th = '#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#* ผูกกับผู้บัญชาการระดับสูงเพื่อเริ่มภารกิจรวมตัว สำเร็จภารกิจเพื่อรับรางวัล และยังสามารถรับแต้มคะแนนจากผู้บัญชาการที่ผูกไว้ด้วย',
		text_ph = '#C0xD26B5C##L00100010##LOC0xFFFFFF##LOS2#* Mag-bind ng isang mataas na antas na commander upang simulan ang reunion na gawain. Tapusin ang gawain upang makuha ang gantimpala. Bukod pa rito, maaari ka ring makakuha ng mga puntos mula sa bind na commander.'
	},
	[7766] = {
		id = 7766,
		key = 'reunionBindTextBySenior',
		text = '#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#* Congratulations, you have successfully linked with player [ #L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C# >! Help the player return and complete the mission to receive reunion rewards!',
		text_vn = '#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#* Chúc mừng bạn đã liên kết thành công với người chơi [ #L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C# >! Hỗ trợ người chơi quay lại hoàn thành nhiệm vụ để nhận quà tái hợp!',
		text_ma = '#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#* Tahniah, anda telah berjaya berhubung dengan pemain [ #L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C# >! Sokong pemain kembali untuk menyelesaikan misi bagi menerima hadiah pertemuan semula!',
		text_en = '#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#* Congratulations, you have successfully linked with player [ #L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C# >! Help the player return and complete the mission to receive reunion rewards!',
		text_in = '#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#* Selamat Anda telah berhasil terhubung dengan pemain [ #L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C# >! Dukung pemain untuk kembali dan selesaikan misi untuk menerima hadiah reuni!',
		text_th = '#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#* ยินดีด้วยที่คุณเชื่อมโยงสำเร็จกับผู้เล่น [ #L00100010##LOC0xFFFFFF##LOS2##C0xF13B54#%s#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C# >! ช่วยเหลือผู้เล่นในการกลับมาและทำภารกิจเพื่อรับของขว้าต้อนรับกลับ!',
		text_ph = '#L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C#* Binabati kita, matagumpay mong nakakonekta ang manlalaro [ #L00100010##LOC0xFFFFFF##LOS2##C0xF13B54# %s #L00100010##LOC0xFFFFFF##LOS2##C0xD26B5C# >! Tumulong sa manlalaro na magbalik at tapusin ang gawain para makuha ang reunion na gantimpala!'
	},
	[7767] = {
		id = 7767,
		key = 'reunionRule',
		text = 'Commander Reunion Rules',
		text_vn = 'Quy tắc đoàn tụ chỉ huy',
		text_ma = 'Peraturan pertemuan komander',
