	[7789] = {
		id = 7789,
		key = 'cloneBattleKickTip1',
		text = 'In this room, at least 3 people must complete the challenge, and they must stay in the room for at least 3 hours without participating in the challenge before they can be used!',
		text_vn = 'Trong phòng này, ít nhất phải có 3 người hoàn thành thử thách, và người đó phải ở lại phòng ít nhất 3 giờ mà không tham gia thử thách thì mới được sử dụng!',
		text_ma = 'Di dalam bilik ini, sekurang-kurangnya 3 orang perlu menyelesaikan cabaran, dan mereka perlu berada di dalam bilik sekurang-kurangnya 3 jam tanpa menyertai cabaran sebelum ia boleh digunakan!',
		text_en = 'In this room, at least 3 people must complete the challenge, and they must stay in the room for at least 3 hours without participating in the challenge before they can be used!',
		text_in = 'Dalam ruangan ini, setidaknya harus ada 3 orang yang menyelesaikan tantangan, dan orang tersebut harus tinggal di ruangan selama minimal 3 jam tanpa ikut tantangan untuk dapat digunakan!',
		text_th = 'ในห้องนี้ ต้องมีอย่างน้อย 3 คนที่ผ่านการท้าทาย และบุคคลนั้นต้องอยู่ในห้องไม่น้อยกว่า 3 ชั่วโมงโดยไม่เข้าร่วมท้าทายจึงจะสามารถใช้งานได้!',
		text_ph = 'Sa silid na ito, kailangang mayroong hindi bababa sa 3 tao na natapos ang hamon, at ang mga tao ay kailangang manatili sa silid nang hindi bababa sa 3 oras nang hindi lumalahok sa hamon bago magamit ito!'
	},
	[7790] = {
