	[7910] = {
		id = 7910,
		key = 'onSwitchChangeShape',
		text = 'The first conversion requires #C0x5C9970#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B# (#C0x5C9970#Subsequent conversions of the same hero will not cost any diamond; #C0xF76B45# but new heroes of the same line still require consumption of the same diamond #C0x5B545B# when converting). Do you want to continue? (After conversion, all training will be fully inherited)',
		text_vn = 'Lần chuyển đổi đầu tiên cần tiêu tốn #C0x5C9970#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B# (#C0x5C9970#Việc chuyển đổi tiếp theo của cùng một anh hùng sẽ không tốn bất kỳ chi phí nào; #C0xF76B45# nhưng các anh hùng mới của cùng dòng vẫn cần tiêu thụ cùng một viên kim cương #C0x5B545B# khi chuyển đổi). Bạn có muốn tiếp tục không? (Sau khi chuyển đổi hình thức, toàn bộ tu luyện sẽ được kế thừa hoàn toàn)',
		text_ma = 'Pertukaran pertama memerlukan penggunaan #C0x5C9970#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B# (#C0x5C9970#Pertukaran seterusnya bagi wira yang sama tidak akan dikenakan sebarang kos; #C0xF76B45# tetapi wira baru dalam cabang yang sama masih memerlukan penggunaan batu permata yang sama #C0x5B545B# semasa pertukaran). Adakah anda pasti ingin teruskan? (Setelah pertukaran bentuk, semua latihan akan diteruskan sepenuhnya)',
		text_en = 'The first conversion requires #C0x5C9970#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B# (#C0x5C9970#Subsequent conversions of the same hero will not cost any diamond; #C0xF76B45# but new heroes of the same line still require consumption of the same diamond #C0x5B545B# when converting). Do you want to continue? (After conversion, all training will be fully inherited)',
		text_in = 'Untuk konversi pertama, Anda perlu menghabiskan #C0x5C9970#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B# (#C0x5C9970#Konversi berikutnya dari pahlawan yang sama tidak akan memerlukan biaya apapun; #C0xF76B45# Namun, pahlawan baru dengan jenis yang sama masih perlu menghabiskan jumlah berlian yang sama #C0x5B545B# saat melakukan konversi). Apakah Anda ingin melanjutkan? (Setelah konversi bentuk, semua pelatihan akan diwariskan sepenuhnya)',
		text_th = 'การเปลี่ยนครั้งแรกต้องใช้ #C0x5C9970#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B# (#C0x5C9970#การเปลี่ยนในครั้งถัดไปของฮีโร่เดียวกันจะไม่เสียค่าใช้จ่ายใด ๆ; #C0xF76B45#แต่ฮีโร่ใหม่ในสายเดียวกันยังต้องใช้เพชรเท่าเดิม #C0x5B545B#) คุณต้องการดำเนินการต่อหรือไม่? (หลังจากเปลี่ยนรูปแบบ การฝึกฝนทั้งหมดจะสืบทอดอย่างสมบูรณ์)',
		text_ph = 'Ang unang conversion ay mangangailangan ng #C0x5C9970#%d#Icommon/icon/icon_diamond.png-56-56##C0x5B545B# (#C0x5C9970#Ang mga susunod na conversion para sa parehong hero ay hindi na kakailanganin ng anumang gastos; #C0xF76B45# ngunit ang mga bagong heroes ng parehong line ay kailangan pa ring gumamit ng isang diamond #C0x5B545B# sa conversion). Gusto mo bang magpatuloy? (Pagkatapos ng conversion ng form, lahat ng training ay magiging fully inherited)'
	},
	[7911] = {
		id = 7911,
		key = 'onSwitchChangeShape1',
		text = 'Select this model',
		text_vn = 'Sắp chuyển sang hình thức mới, bạn có muốn tiếp tục không? (Sau khi chuyển nhánh, mọi sự phát triển sẽ được kế thừa hoàn toàn)',
		text_ma = 'Anda akan beralih ke bentuk baru, adakah anda pasti ingin teruskan? (Setelah beralih cabang, semua perkembangan akan diteruskan sepenuhnya)',
		text_en = 'Select this model',
		text_in = 'Segera beralih ke bentuk baru, apakah Anda ingin melanjutkan? (Setelah mengubah cabang, semua perkembangan akan diwariskan sepenuhnya)',
		text_th = 'คุณกำลังจะเปลี่ยนเป็นรูปแบบใหม่ ต้องการดำเนินการต่อหรือไม่? (หลังจากเปลี่ยนสาย การพัฒนาทั้งหมดจะสืบทอดอย่างสมบูรณ์)',
		text_ph = 'Malapit nang magsimula ang conversion form, gusto mo bang magpatuloy? (Pagkatapos ng branch change, ang lahat ng development ay magiging fully inherited)'
	},
