	[7927] = {
		id = 7927,
		key = 'qualityExchangeFragmentExchangeTip',
		text = 'Diamonds are about to be used to convert %s in your backpack into %s needed. Do you want to continue? (%s#C0x5B545B# will be consumed after conversion)',
		text_vn = 'Kim cương sắp được dùng để chuyển đổi %s trong ba lô thành %s cần thiết. Bạn có muốn tiếp tục không? (%s#C0x5B545B# sẽ được tiêu thụ sau khi chuyển đổi)',
		text_ma = 'Batu permata akan digunakan untuk menukar %s dalam beg anda kepada %s yang diperlukan. Adakah anda pasti ingin meneruskan? (%s#C0x5B545B# akan digunakan selepas penukaran)',
		text_en = 'Diamonds are about to be used to convert %s in your backpack into %s needed. Do you want to continue? (%s#C0x5B545B# will be consumed after conversion)',
		text_in = 'Berlian akan segera digunakan untuk mengonversi %s di tas menjadi %s yang dibutuhkan. Apakah Anda ingin melanjutkan? (%s#C0x5B545B# akan dikonsumsi setelah konversi)',
		text_th = 'กำลังจะใช้เพชรเพื่อแปลง %s ในกระเป๋าเป็น %s ที่จำเป็น คุณต้องการดำเนินการต่อหรือไม่? (%s#C0x5B545B# จะถูกใช้หลังจากการแปลง)',
		text_ph = 'Ang diamonds ay malapit nang gamitin upang i-convert ang %s sa iyong backpack sa %s na kailangan. Gusto mo bang magpatuloy? (%s#C0x5B545B# ay makokonsumo pagkatapos ng conversion)'
	},
	[7928] = {
		id = 7928,
		key = 'changeNatureToChangeTeam',
		text = 'Changing the attributes of the hero will lead to changes in some strategic team formations, please adjust the teams accordingly.',
		text_vn = 'Thay đổi thuộc tính của anh hùng được dẫn đến sự thay đổi trong một số đội hình chiến thuật, vui lòng điều chỉnh đội ngũ kịp thời.',
		text_ma = 'Perubahan atribut wira akan menyebabkan perubahan dalam beberapa formasi strategi, sila sesuaikan pasukan anda dengan segera.',
		text_en = 'Changing the attributes of the hero will lead to changes in some strategic team formations, please adjust the teams accordingly.',
		text_in = 'Perubahan atribut pahlawan akan mengarah pada perubahan dalam beberapa formasi taktis, harap sesuaikan tim dengan tepat.',
		text_th = 'การเปลี่ยนแปลงคุณสมบัติของฮีโร่นำไปสู่การเปลี่ยนแปลงในบางทีมรบ กรุณาปรับทีมให้ทันเวลา',
		text_ph = 'Ang pagbabago ng hero attributes ay magdudulot ng pagbabago sa ilang team strategy, mangyaring i-adjust ang lineup nang maaga.'
	},
