	[7933] = {
		id = 7933,
		key = 'gymReset',
		text = '#C0xFFFFFF# All #C0x3C8B99#mandatory dungeons #C0xFFFFFF#, #C0x3C8B99#Lord of Honor #C0xFFFFFF# and #C0x3C8B99#Challenge Rewards #C0xFFFFFF# have begun to reset, and a new challenge is about to begin!',
		text_vn = '#C0xFFFFFF# Tất cả #C0x3C8B99# bản sao bắt buộc #C0xFFFFFF#, #C0x3C8B99#Chúa tể danh dự #C0xFFFFFF# và #C0x3C8B99#Phần thưởng thử thách #C0xFFFFFF# đã bắt đầu thiết lập lại và một thử thách mới sắp bắt đầu!',
