	[8106] = {
		id = 8106,
		key = 'rmbRewardTips',
		text = 'Spend diamonds to increase your refund rate! \n The more you spend, the higher the refund rate! Additional prizes will also be awarded!',
		text_vn = 'Hãy tiêu kim cương để tăng tỷ lệ hoàn tiền của bạn! \nTỷ lệ hoàn tiền càng cao khi bạn chi tiêu càng nhiều! Ngoài ra còn có các giải thưởng bổ sung được trao đi!',
		text_ma = 'Belanjakan berlian untuk meningkatkan kadar pulangan anda! \nKadar pulangan lebih tinggi apabila anda membelanjakan lebih banyak! Selain itu, terdapat hadiah tambahan yang diberikan!',
		text_en = 'Spend diamonds to increase your refund rate! \n The more you spend, the higher the refund rate! Additional prizes will also be awarded!',
		text_in = 'Habiskan berlian Anda untuk meningkatkan rasio pengembalian Anda! \n Rasio pengembalian semakin tinggi semakin banyak Anda menghabiskan! Selain itu, ada hadiah tambahan yang diberikan!',
		text_th = 'ใช้เพชรเพื่อเพิ่มอัตราการคืนเงิน! \nยิ่งใช้จ่ายมาก อัตราคืนเงินยิ่งสูง! ยังมีของรางวัลพิเศษอีกมากมาย!',
		text_ph = 'Gumastos ng mga hiyas upang madagdagan ang iyong cashback rate! \n Mas mataas ang cashback rate kapag gumastos ka nang mas marami! Mayroon ding karagdagang mga gantimpala na ipamimigay!'
	},
	[8107] = {
		id = 8107,
		key = 'rmbRewardFixTips',
		text = 'Spend diamonds to get a discount rate! \n The more you spend, the more discounts you get! Additional prizes will also be awarded!',
		text_vn = 'Hãy tiêu kim cương và nhận được khoản giảm giá theo tỷ lệ! \nBạn chi tiêu càng nhiều, bạn càng nhận được nhiều chiết khấu! Ngoài ra còn có các giải thưởng bổ sung được trao đi!',
		text_ma = 'Belanjakan berlian dan terima diskaun mengikut kadar! \nAnda belanjakan lebih banyak, anda terima lebih banyak diskaun! Selain itu, terdapat hadiah tambahan yang diberikan!',
		text_en = 'Spend diamonds to get a discount rate! \n The more you spend, the more discounts you get! Additional prizes will also be awarded!',
		text_in = 'Habiskan berlian Anda dan dapatkan diskon sesuai rasio! \n Semakin banyak Anda menghabiskan, semakin banyak diskon yang Anda terima! Selain itu, ada hadiah tambahan yang diberikan!',
		text_th = 'ใช้เพชรเพื่อรับส่วนลดตามอัตราส่วน! \nยิ่งใช้จ่ายมาก ส่วนลดยิ่งมาก! ยังมีของรางวัลพิเศษอีกมากมาย!',
		text_ph = 'Gumastos ng hiyas at makuha ang iyong diskwento ayon sa rate! \n Kung mas marami kang ginagastos, mas mataas ang iyong diskwento! Mayroon ding karagdagang mga gantimpala na ipamimigay!'
	},
	[8108] = {
		id = 8108,
		key = 'rmbRewardEndTips',
		text = 'The event has ended! \n The diamonds you spent will no longer be accumulated or discounted! Claim your discount now!',
		text_vn = 'Sự kiện đã kết thúc! \nSố kim cương đã tiêu thụ sẽ không còn được tích lũy hoặc giảm giá nữa! Nhận giảm giá của bạn ngay bây giờ!',
		text_ma = 'Acara telah berakhir! \nJumlah berlian yang dibelanjakan tidak akan lagi dikumpul atau didiskaunkan! Ambil diskaun anda sekarang!',
		text_en = 'The event has ended! \n The diamonds you spent will no longer be accumulated or discounted! Claim your discount now!',
		text_in = 'Acara telah berakhir! \n Jumlah berlian yang telah dibelanjakan tidak akan lagi dihitung atau didiskon! Dapatkan diskon Anda sekarang!',
		text_th = 'กิจกรรมสิ้นสุดแล้ว! \nจำนวนเพชรที่ใช้จะไม่ถูกนับหรือให้ส่วนลดอีก! รับส่วนลดของคุณตอนนี้เลย!',
		text_ph = 'Natapos na ang kaganapan! \n Hindi na magiging katanggap-tanggap ang mga ginastos na hiyas at hindi na ito maitatala o mabibigyan ng diskwento! Kunin ang iyong diskwento ngayon!'
	},
	[8109] = {
		id = 8109,
		key = 'rmbRewardBottonTips',
		text = 'Note: The Meow Meow wealth gathering activity does not belong to the return-on-investment activity category.',
		text_vn = 'Chú: Chiêu tài meo meo các loại giống như hoạt động không thuộc về bản hoạt động trở lại lợi tích lũy phạm trù',
		text_ma = 'Nota: Promosi seperti Meo Meo tidak termasuk dalam kategori promosi semula keuntungan terkumpul',
		text_en = 'Note: The Meow Meow wealth gathering activity does not belong to the return-on-investment activity category.',
		text_in = 'Catatan: Kegiatan "Meo meo" dan sejenisnya bukan bagian dari acara kembali ke keuntungan dan akumulasi kategori',
		text_th = 'หมายเหตุ: กิจกรรมต่างๆ เช่น แมวเรียกโชค ไม่อยู่ในขอบเขตสะสมผลตอบแทนของกิจกรรมรีเทิร์น',
		text_ph = 'Paalala: Ang mga "Meow Meow" lottery event ay hindi bahagi ng kasalukuyang kaganapan at hindi makakakuha ng mga bonus mula sa mga aktibidad na nauugnay sa kabuuang benepisyo.'
	},
