	[8147] = {
		id = 8147,
		key = 'dailyAssistantFishTip',
		text = 'Skip fishing in the fishing competition is not enabled, during the fishing competition, pressing once will still consume a fishing attempt. Are you sure you want to cancel?',
		text_vn = 'Không mở "Bỏ qua câu cá trong giải đấu câu cá", trong thời gian giải đấu câu cá, việc ấn một lần vẫn sẽ tiêu tốn lượt câu cá, bạn có chắc chắn muốn hủy không?',
		text_ma = 'Jangan buka "Langkau memancing dalam pertandingan", semasa acara pertandingan memancing, klik sekali masih akan menggunakan giliran memancing, anda pasti mahu batal? ',
		text_en = 'Skip fishing in the fishing competition is not enabled, during the fishing competition, pressing once will still consume a fishing attempt. Are you sure you want to cancel?',
		text_in = 'Tidak mengaktifkan "Lewati memancing dalam turnamen memancing", selama periode turnamen memancing, menekan satu kali tetap akan menghabiskan giliran memancing, apakah kamu yakin ingin membatalkan?',
		text_th = 'ยังไม่เปิดใช้งาน “ข้ามการตกปลาในการแข่งขันตกปลา” หากคุณกดครั้งเดียวในช่วงกิจกรรมจะเสียโอกาสตกปลา คุณแน่ใจหรือไม่ว่าจะยกเลิก?',
		text_ph = 'Hindi pa naka-enable ang "I-skip ang pangingisda sa fishing competition", sa panahon ng fishing competition, ang isang pag-click ay tatanggalin pa rin ang isang pagkakataon ng pangingisda, sigurado ka bang nais mong kanselahin?'
	},
