	[8261] = {
		id = 8261,
		key = 'preventFraudChatTips',
		text = 'Dear Commander, please do not trust any advertising information like recharge discounts from the World Channel and beware of accounts bought through private chat. These are online scams! If you encounter any suspicious information, please contact customer service for feedback. I wish you a happy gaming experience!',
		text_vn = 'Kính gửi Chỉ huy, vui lòng không tin bất kỳ thông tin quảng cáo nào như giảm giá nạp tiền của Kênh Thế giới và cảnh giác với các tài khoản được mua thông qua trò chuyện riêng tư với tài khoản. Đây đều là những trò lừa đảo trực tuyến! Nếu bạn gặp bất kỳ thông tin đáng ngờ nào, vui lòng liên hệ với bộ phận dịch vụ khách hàng để được phản hồi. Tôi chúc bạn một trò chơi vui vẻ!',
		text_ma = 'Kepada Komander, jangan percaya sebarang iklan diskaun tambah nilai dalam Saluran Dunia dan waspada terhadap akaun dibeli melalui sembang peribadi. Ini semua adalah penipuan dalam talian! Jika anda temui maklumat mencurigakan, sila hubungi khidmat pelanggan. Selamat bermain! ',
		text_en = 'Dear Commander, please do not trust any advertising information like recharge discounts from the World Channel and beware of accounts bought through private chat. These are online scams! If you encounter any suspicious information, please contact customer service for feedback. I wish you a happy gaming experience!',
		text_in = 'Kepada Komandan, harap tidak percaya iklan diskon top-up apa pun di Channel Dunia dan waspadai akun yang dijual lewat pesan pribadi. Itu semua adalah penipuan online! Jika menemukan info mencurigakan, hubungi layanan pelanggan segera. Selamat bermain!',
		text_th = 'เรียน ผู้บัญชาการ โปรดอย่าเชื่อโฆษณาการเติมเงินลดราคาในช่องทางโลกและระวังบัญชีที่ถูกซื้อผ่านแชทส่วนตัวกับบัญชีอื่น นี่คือการหลอกลวงทางออนไลน์! หากพบข้อมูลที่น่าสงสัย โปรดติดต่อฝ่ายบริการลูกค้าเพื่อรับการตอบกลับ ขอให้สนุกกับการเล่นเกม!',
		text_ph = 'Minamahal na Komandante, huwag magtiwala sa anumang impormasyon ng mga ad na nag-aalok ng diskwento sa top-up mula sa World Channel at mag-ingat sa mga account na binili sa pamamagitan ng private messages. Ang mga ito ay mga online scam! Kung nakatagpo ka ng anumang kahina-hinalang impormasyon, mangyaring makipag-ugnay sa customer service para sa feedback. Nais ko sa iyo ang isang masayang laro!'
	},
	[8262] = {
		id = 8262,
		key = 'preventFraudPosterTitle',
		text = '#Pfont/youmi.ttf# Be cautious to avoid account scams',
		text_vn = '#Pfont/youmi.ttf# Đề cao cảnh giác, để phòng tài khoản lừa gạt',
		text_ma = '#Pfont/youmi.ttf# Waspada, elak akaun penipu ',
		text_en = '#Pfont/youmi.ttf# Be cautious to avoid account scams',
		text_in = '#Pfont/youmi.ttf# Tingkatkan kewaspadaan, hindari akun penipuan',
		text_th = '#Pfont/youmi.ttf# ระวังเพื่อป้องกันบัญชีถูกหลอกลวง',
		text_ph = '#Pfont/youmi.ttf# Mag-ingat, upang maiwasan ang mga pekeng account'
	},
	[8263] = {
		id = 8263,
		key = 'preventFraudPosterDes1',
		text = '#Pfont/youmi.ttf# Common tricks: \n#Pfont/youmi.ttf# Private chat to buy coins, not going through the official platform!\n Fake high prices, trying to entice transactions!\n Fake delivery of goods, trying to scam transaction fees!',
		text_vn = '#Pfont/youmi.ttf# Thủ pháp quen dùng: \n#Pfont/youmi.ttf# Nói chuyện riêng mua hào, không đi chính quy bình đài!\n Ra giá hư cao, ý đồ dẫn dụ giao dịch!\n Giao dịch xách hiện, còn muốn lừa gạt phí thủ tục!',
		text_ma = '#Pfont/youmi.ttf# Taktik biasa: \n#Pfont/youmi.ttf# Beli akaun secara peribadi, tidak melalui platform rasmi!\n Harga palsu tinggi, niat menipu!\n Transaksi tunai, tipu yuran! ',
		text_en = '#Pfont/youmi.ttf# Common tricks: \n#Pfont/youmi.ttf# Private chat to buy coins, not going through the official platform!\n Fake high prices, trying to entice transactions!\n Fake delivery of goods, trying to scam transaction fees!',
		text_in = '#Pfont/youmi.ttf# Cara umum: \n#Pfont/youmi.ttf# Obrolan pribadi beli akun, tidak lewat platform resmi!\n Harga palsu tinggi, coba pancing transaksi!\n Transaksi pihak ketiga, bahkan minta biaya tambahan!',
		text_th = '#Pfont/youmi.ttf# เทคนิคที่ใช้บ่อย: \n#Pfont/youmi.ttf# คุยส่วนตัวซื้อเงิน ไม่ใช้ทางการ! \n ตั้งราคาแพงเกินจริง เพื่อล่อให้ทำธุรกรรม! \n ธุรกรรมแบบหิ้ว ยังจะหลอกค่าธรรมเนียม!',
		text_ph = '#Pfont/youmi.ttf# Karaniwang trick: \n#Pfont/youmi.ttf# Pagpapalitan ng account sa private chat, hindi sa mga regular na channels!\n Nag-aalok ng mataas na pekeng presyo, layunin ay mang-akit ng transaksyon!\n Makikipagtulungan sa mga pekeng bayad sa proseso!'
	},
	[8264] = {
		id = 8264,
		key = 'preventFraudPosterDes2',
		text = '#Pfont/youmi.ttf# Friendly reminder: \n#Pfont/youmi.ttf# Don’t share accounts casually!\n Don’t share orders!\n Don’t unlock phone restrictions casually!\n Make sure to trade through official platforms!',
		text_vn = '#Pfont/youmi.ttf# Hữu nghị nhắc nhở: \n#Pfont/youmi.ttf# Không muốn tùy ý cùng hưởng tài khoản!\n Không muốn cùng hưởng đơn đặt hàng Screenshots!\n Không muốn tùy ý cởi trói điện thoại!\n Giao dịch mời đi chính quy bình đài!',
		text_ma = '#Pfont/youmi.ttf# Peringatan mesra: \n#Pfont/youmi.ttf# Jangan kongsi akaun sesuka hati!\n Jangan kongsi pesanan tangkapan layar!\n Jangan sesuka hati lepaskan ikatan telefon!\n Urus niaga hanya di platform rasmi!',
		text_en = '#Pfont/youmi.ttf# Friendly reminder: \n#Pfont/youmi.ttf# Don’t share accounts casually!\n Don’t share orders!\n Don’t unlock phone restrictions casually!\n Make sure to trade through official platforms!',
		text_in = '#Pfont/youmi.ttf# Peringatan ramah: \n#Pfont/youmi.ttf# Jangan berbagi akun sembarangan!\n Jangan berbagi tangkapan layar pesanan!\n Jangan lepas pengikat HP sembarangan!\n Transaksi silakan lewat platform resmi!',
		text_th = '#Pfont/youmi.ttf# คำแนะนำด้วยความเป็นมิตร: \n#Pfont/youmi.ttf# ไม่ต้องการแบ่งปันบัญชีโดยไม่สมัครใจ! \n ไม่ต้องการแชร์ภาพสกรีนช็อตคำสั่งซื้อ! \n ไม่ต้องการปลดล็อกโทรศัพท์โดยไม่สมัครใจ! \n ขอให้ทำธุรกรรมผ่านช่องทางทางการ!',
		text_ph = '#Pfont/youmi.ttf# Paalala ng pagkakaibigan: \n#Pfont/youmi.ttf# Huwag magbahagi ng account nang hindi naaayon!\n Huwag magbahagi ng order screenshots!\n Huwag i-unlock ang telepono nang hindi tama!\n Gamitin ang mga lehitimong channels para sa transaksyon!'
	},
