		key = 'volleyballSkill2',
		text = '#C0x5B545B#[Charge the ball>\n When charging, you cannot jump, movement speed will slow down, but the longer you charge, \n the ball will hit harder.]',
		text_vn = '#C0x5B545B#[tích lực đánh bóng>\n khi tích lực, bạn không thể nhảy, tốc độ di chuyển sẽ chậm lại, nhưng thời gian tích lực càng lâu\n bóng đánh ra sẽ càng mạnh.',
		text_ma = '#C0x5B545B#[tahan tenaga untuk pukulan>\n semasa menahan tenaga, anda tidak boleh melompat, kelajuan pergerakan akan menjadi perlahan, tetapi semakin lama anda tahan tenaga\n bola yang dipukul akan semakin kuat.',
		text_en = '#C0x5B545B#[Charge the ball>\n When charging, you cannot jump, movement speed will slow down, but the longer you charge, \n the ball will hit harder.]',
		text_in = '#C0x5B545B#[Charge smash>\n saat charge, kamu tidak bisa melompat, kecepatan gerak melambat, tetapi semakin lama mengisi tenaga \n bola akan semakin kuat.  ',
		text_th = '#C0x5B545B#[สะสมพลังตีบอล>\n ขณะสะสมพลังคุณไม่สามารถกระโดด ความเร็วจะช้าลง แต่ยิ่งสะสมพลังนานบอลจะยิ่งตีแรงขึ้น \n',
		text_ph = '#C0x5B545B#[Power-up strike>\n kapag nag-iipon ng lakas, hindi ka maaaring tumalon, babagal ang bilis ng paggalaw, ngunit ang bola na pinakawalan pagkatapos ng mas matagal na pag-iipon ay magiging mas malakas.'
	},
	[8516] = {
		id = 8516,
		key = 'volleyballSkill3',
		text = '#C0x5B545B#[Ball skill>\n When successfully returning the opponent’s ball, you will accumulate 1 energy point. When there is no energy, \n skills cannot be used.]',
		text_vn = '#C0x5B545B#[kỹ năng bóng>\n khi thành công trả bóng của đối thủ, bạn sẽ tích lũy 1 điểm năng lượng. khi không có năng lượng,\n kỹ năng không thể sử dụng.',
		text_ma = '#C0x5B545B#[kemahiran bola>\n apabila berjaya membalas pukulan lawan, anda akan mengumpul 1 mata tenaga. jika tiada tenaga,\n kemahiran tidak boleh digunakan.',
		text_en = '#C0x5B545B#[Ball skill>\n When successfully returning the opponent’s ball, you will accumulate 1 energy point. When there is no energy, \n skills cannot be used.]',
		text_in = '#C0x5B545B#[Skill bola>\n saat berhasil mengembalikan bola lawan, kamu akan mengumpulkan 1 energi. Jika tidak ada energi, \n skill tidak bisa digunakan.  ',
		text_th = '#C0x5B545B#[สกิลบอล>\n เมื่อโต้กลับบอลของฝ่ายตรงข้ามสำเร็จ คุณจะสะสมพลัง 1 แต้ม หากไม่มีพลัง \n สกิลจะไม่สามารถใช้ได้',
		text_ph = '#C0x5B545B#[Ball skill>\n kapag matagumpay mong nabawi ang bola mula sa kalaban, makakakuha ka ng 1 energy point. Kapag walang energy, hindi magagamit ang skill.'
	},
	[8517] = {
		id = 8517,
		key = 'volleyballSkill4',
		text = '#C0x5B545B#[Ball skill>\n With 3 energy points, you can use level 1 skills at any time. After using, your ball will have a slowing effect, causing the opponent to slow down upon contact.]',
		text_vn = '#C0x5B545B#[kỹ năng bóng>\n với 3 điểm năng lượng, bạn được sử dụng kỹ năng cấp 1 bất kỳ lúc nào. sau khi sử dụng, bóng của bạn sẽ mang thuộc tính làm chậm, khi chạm vào đối thủ sẽ gây hiệu ứng giảm tốc.',
		text_ma = '#C0x5B545B#[kemahiran bola>\n dengan 3 mata tenaga, anda boleh guna kemahiran tahap 1 pada bila-bila masa. selepas digunakan, bola anda akan membawa kesan perlahan, bila mengenai lawan akan memperlahankan mereka.',
		text_en = '#C0x5B545B#[Ball skill>\n With 3 energy points, you can use level 1 skills at any time. After using, your ball will have a slowing effect, causing the opponent to slow down upon contact.]',
		text_in = '#C0x5B545B#[Skill bola>\n dengan 3 energi, kamu bisa gunakan skill level 1 kapan saja. Setelah digunakan, bola akan memiliki efek lambat, menyentuh lawan akan memperlambat mereka.  ',
		text_th = '#C0x5B545B#[สกิลบอล>\n เมื่อมีพลัง 3 แต้ม คุณสามารถใช้สกิลระดับ 1 ได้ทุกเมื่อ หลังใช้ ลูกบอลของคุณจะมีคุณสมบัติชะลอ เมื่อโดนฝ่ายตรงข้ามจะทำให้ช้าลง',
		text_ph = '#C0x5B545B#[Ball skill>\n Kapag mayroon kang 3 energy points, maaari mong gamitin ang level 1 skill kahit kailan. Pagkatapos gamitin, ang bola ay magkakaroon ng slow effect at kapag tumama sa kalaban ay magdudulot ng slow effect.'
	},
	[8518] = {
		id = 8518,
		key = 'volleyballSkill5',
		text = '#C0x5B545B#[Ball skill>\n With 6 energy points, you can use level 2 skills at any time. After using, your ball will have a powerful attack property, and no one can block it! \n Using the skill will consume energy, so be careful when using it.]',
		text_vn = '#C0x5B545B#[kỹ năng bóng>\n với 6 điểm năng lượng, bạn được sử dụng kỹ năng cấp 2 bất kỳ lúc nào. sau khi sử dụng, bóng của bạn sẽ mang thuộc tính tấn công mạnh mẽ, không ai được cản phá! \n sử dụng kỹ năng sẽ tiêu hao năng lượng, hãy chú ý thời điểm sử dụng.',
		text_ma = '#C0x5B545B#[kemahiran bola>\n dengan 6 mata tenaga, anda boleh guna kemahiran tahap 2 pada bila-bila masa. selepas digunakan, bola anda akan mempunyai kuasa serangan kuat, tiada siapa boleh halang! \n penggunaan kemahiran akan menggunakan tenaga, sila pilih masa yang sesuai untuk guna.',
		text_en = '#C0x5B545B#[Ball skill>\n With 6 energy points, you can use level 2 skills at any time. After using, your ball will have a powerful attack property, and no one can block it! \n Using the skill will consume energy, so be careful when using it.]',
		text_in = '#C0x5B545B#[Skill bola>\n dengan 6 energi, kamu bisa gunakan skill level 2 kapan saja. Setelah digunakan, bola memiliki kekuatan serangan dahsyat yang tidak bisa dihentikan! \n penggunaan skill akan menghabiskan energi, perhatikan waktu penggunaannya.  ',
		text_th = '#C0x5B545B#[สกิลบอล>\n เมื่อมีพลัง 6 แต้ม คุณสามารถใช้สกิลระดับ 2 ได้ทุกเมื่อ หลังใช้ ลูกบอลของคุณจะมีคุณสมบัติโจมตีรุนแรง ไม่มีใครหยุดได้! \n การใช้สกิลจะใช้พลังงาน โปรดระวังเวลาใช้',
		text_ph = '#C0x5B545B#[Ball skill>\n Kapag mayroon kang 6 energy points, maaari mong gamitin ang level 2 skill kahit kailan. Pagkatapos gamitin, ang bola ay magkakaroon ng malakas na epekto sa pag-atake, walang makakapigil! \n Ang paggamit ng skill ay mag-aaksaya ng enerhiya, mangyaring gamitin ito ng maayos.'
	},
