	[8530] = {
		id = 8530,
		key = 'zawakeMegaTip',
		text = '#C0xF13B54# Stage %s #C0x5B545B# is about to awaken the soul. After the soul awakens, #L10##C0x88C855# the destiny #L0##C0x5B545B# will be reset. Do you want to continue?',
		text_vn = '#C0xF13B54# Giai đoạn %s #C0x5B545B#sắp thức tỉnh linh hồn. Sau khi thức tỉnh linh hồn, #L10##C0x88C855# mệnh cách #L0##C0x5B545B# sẽ được thiết lập lại. Bạn có muốn tiếp tục không?',
		text_ma = '#C0xF13B54# Peringkat %s #C0x5B545B#akan bangkitkan jiwa. Selepas kebangkitan jiwa, #L10##C0x88C855# takdir #L0##C0x5B545B# akan diset semula. Adakah anda mahu teruskan?',
		text_en = '#C0xF13B54# Stage %s #C0x5B545B# is about to awaken the soul. After the soul awakens, #L10##C0x88C855# the destiny #L0##C0x5B545B# will be reset. Do you want to continue?',
		text_in = '#C0xF13B54# Tahap %s #C0x5B545B#akan segera membangkitkan jiwa. Setelah jiwa dibangkitkan, #L10##C0x88C855# takdir #L0##C0x5B545B# akan direset. Lanjutkan?  ',
		text_th = '#C0xF13B54# ช่วง %s #C0x5B545B# กำลังปลุกวิญญาณ หลังปลุกวิญญาณ #L10##C0x88C855# ชะตา #L0##C0x5B545B# จะถูกรีเซ็ต คุณต้องการดำเนินการต่อไหม?',
		text_ph = '#C0xF13B54# Ang yugto ng %s #C0x5B545B# ay malapit nang magising ang kaluluwa. Pagkatapos magising ang kaluluwa, #L10##C0x88C855# ang kapalaran ng #L0##C0x5B545B# ay mare-reset. Nais mo bang magpatuloy?'
	},
	[8531] = {
		id = 8531,
		key = 'zawakeBranchTip',
		text = '#C0xF13B54# Stage %s #C0x5B545B# is about to branch. After branching, #L10##C0x88C855# the destiny #L0##C0x5B545B# cultivation will be reset. Do you want to continue?',
		text_vn = '#C0xF13B54# Giai đoạn %s #C0x5B545B#sắp được chuyển nhánh, sau khi chuyển nhánh, #L10##C0x88C855# mệnh cách #L0##C0x5B545B# tu luyện sẽ bị đặt lại, bạn có muốn tiếp tục không?',
		text_ma = '#C0xF13B54# Peringkat %s #C0x5B545B#akan bercabang, selepas percabangan, #L10##C0x88C855# takdir latihan #L0##C0x5B545B# akan diset semula, adakah anda mahu teruskan?',
		text_en = '#C0xF13B54# Stage %s #C0x5B545B# is about to branch. After branching, #L10##C0x88C855# the destiny #L0##C0x5B545B# cultivation will be reset. Do you want to continue?',
		text_in = '#C0xF13B54# Tahap %s #C0x5B545B#akan segera berpindah cabang, setelah berpindah, #L10##C0x88C855# takdir pelatihan #L0##C0x5B545B# akan direset. Lanjutkan?  ',
		text_th = '#C0xF13B54# ช่วง %s #C0x5B545B# กำลังเปลี่ยนสาย หลังเปลี่ยนสาย #L10##C0x88C855# ชะตา #L0##C0x5B545B# การฝึกฝนจะถูกรีเซ็ต คุณต้องการดำเนินการต่อไหม?',
		text_ph = '#C0xF13B54# Ang yugto ng %s #C0x5B545B# ay malapit nang magbago ng sanga, at pagkatapos ng pagbabago, #L10##C0x88C855# ang kapalaran ng #L0##C0x5B545B# sa pagsasanay ay mare-reset. Nais mo bang magpatuloy?'
