	[8602] = {
		id = 8602,
		key = 'preliminaryMatchTip',
		text = '#C0x5B545B# Each battle group has only one opportunity to predict. Do you want to use %d#Icommon/icon/icon_ghb.png-56-56# to predict the current guild?',
		text_vn = '#C0x5B545B# Mỗi nhóm chiến đấu chỉ có một cơ hội đoán. Bạn có muốn sử dụng %d#Icommon/icon/icon_ghb.png-56-56# để đoán bang hội hiện tại không?',
		text_ma = '#C0x5B545B#Setiap kumpulan pertempuran hanya mempunyai satu peluang ramalan. Anda mahu guna %d#Icommon/icon/icon_ghb.png-56-56# untuk meramal guild semasa?',
		text_en = '#C0x5B545B# Each battle group has only one opportunity to predict. Do you want to use %d#Icommon/icon/icon_ghb.png-56-56# to predict the current guild?',
		text_in = '#C0x5B545B# Setiap grup hanya memiliki satu kesempatan menebak. Apakah kamu ingin menggunakan %d#Icommon/icon/icon_ghb.png-56-56# untuk menebak guild saat ini?',
		text_th = '#C0x5B545B# แต่ละกลุ่มต่อสู้มีโอกาสทายเพียงหนึ่งครั้ง คุณต้องการใช้ %d#Icommon/icon/icon_ghb.png-56-56# เพื่อทายกิลด์ปัจจุบันไหม?',
		text_ph = '#C0x5B545B# Ang bawat grupo ay may isang pagkakataon lamang upang mag-predict. Nais mo bang gamitin ang %d#Icommon/icon/icon_ghb.png-56-56# upang mag-predict ng kasalukuyang guild?'
	},
	[8603] = {
		id = 8603,
		key = 'finalMatchTip',
		text = '#C0x5B545B#There is only one chance to predict in the finals. Do you want to use %d#Icommon/icon/icon_ghb.png-56-56# guild to predict the current guild name?',
		text_vn = '#C0x5B545B#Chỉ có một cơ hội đoán trong trận chung kết. Bạn có muốn sử dụng %d#Icommon/icon/icon_ghb.png-56-56#xu guild để đoán tên guild hiện tại không?',
