	[8838] = {
		id = 8838,
		key = 'starStopAid2',
		text = '#C0x5B545B#After canceling, the exchange position will start a countdown of #C0xF76B45#%s#C0x5B545B# and during this time, temporary star exchange cannot be performed. Are you sure you want to cancel the temporary star exchange of #C0x5C9970#%s#C0x5B545B# and #C0x3C8B99#%s#C0x5B545B#?',
		text_vn = '#C0x5B545B#Sau khi hủy, vị trí hoán đổi này sẽ bắt đầu đếm ngược #C0xF76B45#%s#C0x5B545B# và trong thời gian đó không thể thực hiện hoán đổi sao tạm thời. Xác nhận hủy hoán đổi sao tạm thời của #C0x5C9970#%s#C0x5B545B# và #C0x3C8B99#%s#C0x5B545B# không?',
		text_ma = '#C0x5B545B#Selepas batal, posisi pertukaran ini akan memulakan undur #C0xF76B45#%s#C0x5B545B# dan tidak boleh buat pertukaran bintang sementara semasa tempoh itu. Sahkan batal pertukaran bintang sementara antara #C0x5C9970#%s#C0x5B545B# dan #C0x3C8B99#%s#C0x5B545B#?',
		text_en = '#C0x5B545B#After canceling, the exchange position will start a countdown of #C0xF76B45#%s#C0x5B545B# and during this time, temporary star exchange cannot be performed. Are you sure you want to cancel the temporary star exchange of #C0x5C9970#%s#C0x5B545B# and #C0x3C8B99#%s#C0x5B545B#?',
		text_in = '#C0x5B545B#Setelah dibatalkan, posisi pertukaran ini akan mulai menghitung mundur selama #C0xF76B45#%s#C0x5B545B# dan selama waktu ini tidak dapat melakukan tukar bintang sementara. Konfirmasi pembatalan tukar bintang sementara antara #C0x5C9970#%s#C0x5B545B# dan #C0x3C8B99#%s#C0x5B545B#?  ',
		text_th = '#C0x5B545B#หลังยกเลิก ตำแหน่งแลกเปลี่ยนนี้จะเริ่มนับถอยหลัง #C0xF76B45#%s#C0x5B545B# และในช่วงเวลานั้นไม่สามารถแลกเปลี่ยนดาวชั่วคราวได้ กรุณายืนยันยกเลิกแลกเปลี่ยนดาวชั่วคราวของ #C0x5C9970#%s#C0x5B545B# กับ #C0x3C8B99#%s#C0x5B545B# หรือไม่?',
		text_ph = '#C0x5B545B#Pagkatapos ng pagkansela, ang posisyon ng palitan ay magsisimulang mag-countdown ng #C0xF76B45#%s#C0x5B545B#, at sa panahong iyon hindi maaaring magsagawa ng pansamantalang palitan ng bituin. Kumpirmahin ang pagkansela ng pansamantalang palitan ng bituin sa pagitan ng #C0x5C9970#%s#C0x5B545B# at #C0x3C8B99#%s#C0x5B545B#?  '
	},
