	[8865] = {
		id = 8865,
		key = 'fetterTips2',
		text = 'The hero is not consumed after evolution and cannot be used as fate or super-evolution material.',
		text_vn = 'Người anh hùng không bị tiêu thụ sau khi tiến hóa và không thể được sử dụng làm vật liệu cho số phận hoặc siêu tiến hóa.',
